/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isCollection = require( '@stdlib/assert/is-collection' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Sets the axis tics label.
* It is the short hand for xAxisData, yAxisData, zAxisData and wAxisData
*
* @private
* @param {Collection} value - array of axis data
* @throws {TypeError} must be a array of array with length 4
*/
function set( value ) {
	if ( !isCollection( value ) || value.length !== 4 ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a array of array with length 4. Value: `%s`.', 'axisTicsLabels', value ) );
	}
	this.xAxisTicsLabels = value[ 0 ];
	this.yAxisTicsLabels = value[ 1 ];
	this.zAxisTicsLabels = value[ 2 ];
	this.wAxisTicsLabels = value[ 3 ];
}


// EXPORTS //

module.exports = set;
